* { margin: 0; padding: 0; box-sizing: border-box; }
body {
  font-family: system-ui, -apple-system, sans-serif;
  background: #e2e8f0; min-height: 100vh;
  display: grid; place-items: center; padding: 20px;
}
.phone {
  width: 100%; max-width: 380px; background: #0f172a; border-radius: 28px;
  padding: 22px; color: #fff; box-shadow: 0 12px 30px rgba(0, 0, 0, .25);
}
header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 10px; }
h1 { font-size: 20px; font-weight: 800; }
header p { font-size: 11px; color: #94a3b8; margin-top: 2px; }
.pct { font-size: 18px; font-weight: 800; color: #38bdf8; }
.progress {
  height: 8px; background: #1e293b; border-radius: 99px; overflow: hidden; margin-bottom: 16px;
}
#bar {
  display: block; height: 100%; width: 0%;
  background: linear-gradient(90deg, #38bdf8, #22c55e);
  transition: width .3s; border-radius: 99px;
}
form { display: flex; gap: 8px; margin-bottom: 14px; }
input {
  flex: 1; background: #1e293b; border: 1px solid #334155; color: #fff;
  border-radius: 10px; padding: 11px 12px; font-size: 14px;
}
form button {
  width: 44px; border: 0; border-radius: 10px; background: #38bdf8;
  color: #0f172a; font-size: 20px; font-weight: 800; cursor: pointer;
}
ul { list-style: none; }
li {
  display: flex; align-items: center; gap: 10px; background: #1e293b;
  border: 1px solid #334155; border-radius: 12px; padding: 10px 12px;
  margin-bottom: 8px; font-size: 14px;
}
li.done span { text-decoration: line-through; color: #64748b; }
.check {
  width: 24px; height: 24px; border-radius: 7px; border: 2px solid #38bdf8;
  background: transparent; color: #0f172a; font-weight: 900; cursor: pointer;
  display: grid; place-items: center;
}
li.done .check { background: #22c55e; border-color: #22c55e; color: #0f172a; }
.del { margin-left: auto; background: transparent; border: 0; color: #64748b; font-size: 18px; cursor: pointer; }
footer { margin-top: 14px; text-align: center; }
#clearBtn {
  background: transparent; border: 1px solid #334155; color: #94a3b8;
  border-radius: 10px; padding: 8px 14px; font-size: 12px; cursor: pointer;
}

let tasks = [
  { id: 1, text: 'Review desain landing page', done: false },
  { id: 2, text: 'Panggilan tim produk', done: true },
  { id: 3, text: 'Siapkan laporan mingguan', done: false },
  { id: 4, text: 'Update dokumentasi API', done: false }
]
let seq = 5
const list = document.getElementById('list')
const form = document.getElementById('form')
const input = document.getElementById('input')

function render() {
  list.innerHTML = ''
  tasks.forEach((t) => {
    const li = document.createElement('li')
    li.className = t.done ? 'done' : ''
    li.innerHTML = `<button class="check" data-id="${t.id}">${t.done ? '✓' : ''}</button><span>${t.text}</span><button class="del" data-id="${t.id}">×</button>`
    list.appendChild(li)
  })
  const done = tasks.filter((t) => t.done).length
  const pct = tasks.length ? Math.round((done / tasks.length) * 100) : 0
  document.getElementById('pct').textContent = pct + '%'
  document.getElementById('bar').style.width = pct + '%'
  document.getElementById('dateLabel').textContent = new Date().toLocaleDateString('id-ID', { weekday: 'long', day: 'numeric', month: 'long' })
}

list.addEventListener('click', (e) => {
  const id = Number(e.target.dataset.id)
  const t = tasks.find((x) => x.id === id)
  if (!t) return
  if (e.target.classList.contains('check')) t.done = !t.done
  if (e.target.classList.contains('del')) tasks = tasks.filter((x) => x.id !== id)
  render()
})

form.addEventListener('submit', (e) => {
  e.preventDefault()
  const text = input.value.trim()
  if (!text) return
  tasks.push({ id: seq++, text, done: false })
  input.value = ''
  render()
})

document.getElementById('clearBtn').addEventListener('click', () => {
  tasks = tasks.filter((t) => !t.done)
  render()
})

render()
